import { createApp } from './app.ts'

const app = createApp()
try {
  await app.listen({ port: 3001, host: '127.0.0.1' })
} catch (error) {
  app.log.error(error)
  process.exitCode = 1
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.once(signal, () => { void app.close() })
}
=================== server/app.ts
import Fastify from 'fastify'
import { readdir } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { join } from 'node:path'

export type MarkdownFile = { source: 'Pi' | 'Claude'; path: string }
export const fixtureRoot = fileURLToPath(new URL('../fixtures/', import.meta.url))

// Only regular files/directories are followed; symlinks cannot escape the fixtures.
export async function listMarkdownFiles(root = fixtureRoot): Promise<MarkdownFile[]> {
  const files: MarkdownFile[] = []
  async function walk(directory: string, source: MarkdownFile['source'], prefix = '') {
    const entries = await readdir(directory, { withFileTypes: true })
    entries.sort((a, b) => a.name.localeCompare(b.name))
    for (const entry of entries) {
      const path = prefix ? `${prefix}/${entry.name}` : entry.name
      if (entry.isDirectory()) await walk(join(directory, entry.name), source, path)
      else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
        files.push({ source, path })
      }
    }
  }
  await walk(join(root, 'pi'), 'Pi')
  await walk(join(root, 'claude'), 'Claude')
  return files
}

export function createApp(root = fixtureRoot) {
  const app = Fastify({ logger: true })
  app.get('/api/files', async (_request, reply) => {
    try {
      return { files: await listMarkdownFiles(root) }
    } catch (error) {
      app.log.error(error, 'Fixture listing failed')
      return reply.code(500).send({ error: 'Unable to list Markdown files. Check that both fixture folders are readable.' })
    }
  })
  return app
}
=================== server/app.test.ts
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtemp, mkdir, rm, symlink, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createApp } from './app.ts'

const expected = [
  { source: 'Pi', path: 'skills/review.md' },
  { source: 'Pi', path: 'workflow.md' },
  { source: 'Claude', path: 'empty.md' },
  { source: 'Claude', path: 'subagents/implementer.md' },
  { source: 'Claude', path: 'workflow.md' },
]

test('API lists exactly all five fixture Markdown files, including empty/nested files', async () => {
  const app = createApp()
  try {
    const response = await app.inject('/api/files')
    assert.equal(response.statusCode, 200)
    assert.deepEqual(response.json(), { files: expected })
    assert.equal((await app.inject('/api/files?root=/tmp')).body, response.body)
  } finally { await app.close() }
})

test('empty folders, symlink exclusion, and unreadable/missing source errors', async () => {
  const root = await mkdtemp(join(tmpdir(), 'md-manager-test-'))
  const app = createApp(root)
  try {
    await mkdir(join(root, 'pi'))
    await mkdir(join(root, 'claude'))
    await writeFile(join(root, 'outside.md'), 'Not in a source folder')
    await symlink(join(root, 'outside.md'), join(root, 'pi', 'linked.md'))
    await symlink(root, join(root, 'claude', 'linked-directory'))
    const empty = await app.inject('/api/files')
    assert.equal(empty.statusCode, 200)
    assert.deepEqual(empty.json(), { files: [] })
    await rm(join(root, 'claude'), { recursive: true })
    const failed = await app.inject('/api/files')
    assert.equal(failed.statusCode, 500)
    assert.match(failed.json().error, /both fixture folders are readable/)
    assert.ok(!failed.body.includes(root))
  } finally {
    await app.close()
    await rm(root, { recursive: true, force: true })
  }
})
=================== tests/listing.spec.ts
import { test, expect } from '@playwright/test'

test('real app lists all five files with source-relative paths', async ({ page, request }) => {
  await expect.poll(async () => (await request.get('http://127.0.0.1:3001/api/files')).status()).toBe(200)
  await page.goto('/')
  await expect(page.getByRole('status')).toHaveText('5 Markdown files')
  const rows = page.locator('tbody tr')
  await expect(rows).toHaveCount(5)
  const expected = [
    ['Pi', 'skills/review.md'], ['Pi', 'workflow.md'],
    ['Claude', 'empty.md'], ['Claude', 'subagents/implementer.md'], ['Claude', 'workflow.md'],
  ]
  for (const [index, cells] of expected.entries()) {
    await expect(rows.nth(index).locator('td')).toHaveText(cells)
  }
  await expect(page.getByText('notes.txt')).toHaveCount(0)
})

test('loading then empty state', async ({ page }) => {
  let release!: () => void
  const wait = new Promise<void>(resolve => { release = resolve })
  await page.route('**/api/files', async route => {
    await wait
    await route.fulfill({ json: { files: [] } })
  })
  await page.goto('/')
  await expect(page.getByRole('status')).toHaveText('Loading Markdown files…')
  release()
  await expect(page.getByRole('status')).toHaveText('No Markdown files found in the Pi or Claude fixture folders.')
  await expect(page.getByRole('table')).toHaveCount(0)
})

for (const failure of ['http', 'network']) {
  test(`${failure} error gives recovery guidance`, async ({ page }) => {
    await page.route('**/api/files', route => failure === 'http'
      ? route.fulfill({ status: 500, json: { error: 'Listing failed' } })
      : route.abort())
    await page.goto('/')
    await expect(page.getByRole('alert')).toContainText('Unable to load Markdown files.')
    await expect(page.getByRole('alert')).toContainText('reload the page')
    await expect(page.getByRole('table')).toHaveCount(0)
  })
}
=================== src/App.tsx
import { useEffect, useState } from 'react'
import './App.css'

type MarkdownFile = { source: 'Pi' | 'Claude'; path: string }
type ListingState =
  | { status: 'loading' }
  | { status: 'ready'; files: MarkdownFile[] }
  | { status: 'error' }

function App() {
  const [state, setState] = useState<ListingState>({ status: 'loading' })

  useEffect(() => {
    const controller = new AbortController()
    async function load() {
      try {
        const response = await fetch('/api/files', { signal: controller.signal })
        if (!response.ok) throw new Error('Listing failed')
        const data = await response.json() as { files: MarkdownFile[] }
        if (!controller.signal.aborted) setState({ status: 'ready', files: data.files })
      } catch {
        if (!controller.signal.aborted) setState({ status: 'error' })
      }
    }
    void load()
    return () => controller.abort()
  }, [])

  return (
    <main>
      <h1>MD Manager</h1>
      <p>Markdown files in the Pi and Claude fixtures. Paths are relative to each source folder.</p>
      {state.status === 'loading' && <p role="status">Loading Markdown files…</p>}
      {state.status === 'error' && (
        <p role="alert">Unable to load Markdown files. Check that the API is running and both fixture folders are readable, then reload the page.</p>
      )}
      {state.status === 'ready' && (state.files.length === 0
        ? <p role="status">No Markdown files found in the Pi or Claude fixture folders.</p>
        : <>
            <p role="status">{state.files.length} Markdown files</p>
            <table>
              <caption>Available Markdown files</caption>
              <thead><tr><th scope="col">Source</th><th scope="col">Relative path</th></tr></thead>
              <tbody>{state.files.map(file => (
                <tr key={`${file.source}/${file.path}`}>
                  <td>{file.source}</td><td><code>{file.path}</code></td>
                </tr>
              ))}</tbody>
            </table>
          </>)}
    </main>
  )
}

export default App
