import Fastify from 'fastify'
import { lstat, readdir } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { join, resolve } from 'node:path'

export type Source = 'Pi' | 'Claude'
export type EntryKind = 'directory' | 'file'
export type Entry = { source: Source; path: string; kind: EntryKind }

/** Default root: the committed fixtures, resolved from this module rather than the shell's working directory. */
export const defaultFixtureRoot = fileURLToPath(new URL('../fixtures/', import.meta.url))
/** Environment variable that points at an alternative root containing `pi/` and `claude/` subdirectories. */
export const fixtureRootVariable = 'MD_MANAGER_FIXTURE_ROOT'

export function resolveFixtureRoot(env: NodeJS.ProcessEnv = process.env): string {
  const override = env[fixtureRootVariable]?.trim()
  return override ? resolve(override) : defaultFixtureRoot
}

const sources: ReadonlyArray<readonly [Source, string]> = [['Pi', 'pi'], ['Claude', 'claude']]

// Code-unit comparison keeps the order identical on every machine and locale.
function byName(a: { name: string }, b: { name: string }): number {
  return a.name < b.name ? -1 : a.name > b.name ? 1 : 0
}

/**
 * Lists every directory and regular `.md` file (case-insensitive) beneath both sources as one flat list,
 * parents before descendants, sorted by name within each directory. Symlinks are never followed, so
 * nothing outside the root can be reached. Contents are never read.
 */
export async function listEntries(root = resolveFixtureRoot()): Promise<Entry[]> {
  const entries: Entry[] = []
  async function walk(directory: string, source: Source, prefix: string): Promise<void> {
    const dirents = (await readdir(directory, { withFileTypes: true })).sort(byName)
    for (const dirent of dirents) {
      const path = prefix ? `${prefix}/${dirent.name}` : dirent.name
      if (dirent.isDirectory()) {
        entries.push({ source, path, kind: 'directory' })
        await walk(join(directory, dirent.name), source, path)
      } else if (dirent.isFile() && dirent.name.toLowerCase().endsWith('.md')) {
        entries.push({ source, path, kind: 'file' })
      }
    }
  }
  for (const [source, folder] of sources) {
    const directory = join(root, folder)
    const stats = await lstat(directory)
    if (!stats.isDirectory()) throw new Error(`Source folder "${folder}" is not a regular directory`)
    await walk(directory, source, '')
  }
  return entries
}

export function createApp(root = resolveFixtureRoot()) {
  const app = Fastify({ logger: true })
  app.get('/api/entries', async (_request, reply) => {
    try {
      return { entries: await listEntries(root) }
    } catch (error) {
      app.log.error(error, 'Fixture discovery failed')
      return reply.code(500).send({
        error: 'Unable to list Markdown folders. Check that both fixture folders (pi and claude) exist, are regular directories and are readable.',
      })
    }
  })
  return app
}
