export type Source = 'Pi' | 'Claude'
export type EntryKind = 'directory' | 'file'
export type Entry = { source: Source; path: string; kind: EntryKind }
export type FolderContents = { folders: Entry[]; files: Entry[] }
/** Keyed by `folderKey(source, path)`; the root of each source is always present. */
export type FolderIndex = Map<string, FolderContents>

export const sources: readonly Source[] = ['Pi', 'Claude']

export function folderKey(source: Source, path: string): string {
  return `${source}:${path}`
}

export function entryName(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

const collator = new Intl.Collator('en', { sensitivity: 'base', numeric: true })

export function compareEntries(a: Entry, b: Entry): number {
  return collator.compare(entryName(a.path), entryName(b.path)) || (a.path < b.path ? -1 : a.path > b.path ? 1 : 0)
}

/** Builds the folder tree once from the flat entries list; each folder lists its immediate, sorted children. */
export function buildFolderIndex(entries: readonly Entry[]): FolderIndex {
  const index: FolderIndex = new Map()
  const ensure = (key: string): FolderContents => {
    let contents = index.get(key)
    if (!contents) {
      contents = { folders: [], files: [] }
      index.set(key, contents)
    }
    return contents
  }
  for (const source of sources) ensure(folderKey(source, ''))
  for (const entry of entries) {
    const parentPath = entry.path.slice(0, Math.max(0, entry.path.lastIndexOf('/')))
    const parent = ensure(folderKey(entry.source, parentPath))
    if (entry.kind === 'directory') {
      parent.folders.push(entry)
      ensure(folderKey(entry.source, entry.path))
    } else {
      parent.files.push(entry)
    }
  }
  for (const contents of index.values()) {
    contents.folders.sort(compareEntries)
    contents.files.sort(compareEntries)
  }
  return index
}
