import { sources, type Source } from './entries.ts'

export type Route =
  | { kind: 'home' }
  | { kind: 'folder'; source: Source; segments: string[] }
  | { kind: 'not-found' }

const sourceSlug: Record<Source, string> = { Pi: 'pi', Claude: 'claude' }

export const homeHref = '/'

/** `/pi/a%20b/c` — every segment is percent-encoded so spaces, `#`, `?` and `%` survive. */
export function folderHref(source: Source, segments: readonly string[]): string {
  return '/' + [sourceSlug[source], ...segments].map(segment => encodeURIComponent(segment)).join('/')
}

export function parseRoute(pathname: string): Route {
  const raw = pathname.split('/').slice(1)
  if (raw.length > 0 && raw[raw.length - 1] === '') raw.pop()
  if (raw.length === 0) return { kind: 'home' }
  let segments: string[]
  try {
    segments = raw.map(segment => decodeURIComponent(segment))
  } catch {
    return { kind: 'not-found' }
  }
  const slug = segments[0].toLowerCase()
  const source = sources.find(candidate => sourceSlug[candidate] === slug)
  const folderSegments = segments.slice(1)
  if (!source || folderSegments.some(segment => segment === '')) return { kind: 'not-found' }
  return { kind: 'folder', source, segments: folderSegments }
}
