import { createContext, useCallback, useContext, useEffect, useLayoutEffect, useRef, useState } from 'react'

export type Navigate = (href: string) => void

export const NavigateContext = createContext<Navigate>(() => {})

export function useNavigate(): Navigate {
  return useContext(NavigateContext)
}

type HistoryState = { scrollY?: number } | null

/**
 * History-API location. Pushing a link starts the new page at the top; travelling back or forward
 * through history restores the scroll position the listing had when it was left.
 */
export function useBrowserLocation(): [string, Navigate] {
  const [pathname, setPathname] = useState(() => window.location.pathname)
  const pendingScroll = useRef<number | null>(null)

  useEffect(() => {
    if ('scrollRestoration' in window.history) window.history.scrollRestoration = 'manual'
    const onPopState = (event: PopStateEvent) => {
      pendingScroll.current = (event.state as HistoryState)?.scrollY ?? 0
      setPathname(window.location.pathname)
    }
    window.addEventListener('popstate', onPopState)
    return () => window.removeEventListener('popstate', onPopState)
  }, [])

  useLayoutEffect(() => {
    if (pendingScroll.current === null) return
    window.scrollTo(0, pendingScroll.current)
    pendingScroll.current = null
  }, [pathname])

  const navigate = useCallback<Navigate>(href => {
    window.history.replaceState({ scrollY: window.scrollY } satisfies HistoryState, '')
    window.history.pushState({ scrollY: 0 } satisfies HistoryState, '', href)
    pendingScroll.current = 0
    setPathname(window.location.pathname)
  }, [])

  return [pathname, navigate]
}
