import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import './App.css'
import { Breadcrumbs, crumbsForRoute } from './Breadcrumbs.tsx'
import { buildFolderIndex, type Entry } from './entries.ts'
import { FolderView, MissingFolder, SourceCards } from './FolderView.tsx'
import { RefreshIcon } from './icons.tsx'
import { NavigateContext, useBrowserLocation } from './router.ts'
import { parseRoute } from './routing.ts'

type Listing = {
  /** Last successful response, kept while a refresh is pending or has failed. */
  entries: Entry[] | null
  status: 'loading' | 'ready' | 'refreshed' | 'failed'
}

function App() {
  const [pathname, navigate] = useBrowserLocation()
  const route = useMemo(() => parseRoute(pathname), [pathname])
  const [listing, setListing] = useState<Listing>({ entries: null, status: 'loading' })
  const controller = useRef<AbortController | null>(null)

  const load = useCallback(async () => {
    controller.current?.abort()
    const current = new AbortController()
    controller.current = current
    setListing(previous => ({ ...previous, status: 'loading' }))
    try {
      const response = await fetch('/api/entries', { signal: current.signal })
      if (!response.ok) throw new Error(`Listing failed with HTTP ${response.status}`)
      const data = await response.json() as { entries: Entry[] }
      if (current.signal.aborted) return
      setListing(previous => ({ entries: data.entries, status: previous.entries ? 'refreshed' : 'ready' }))
    } catch {
      if (current.signal.aborted) return
      setListing(previous => ({ ...previous, status: 'failed' }))
    }
  }, [])

  useEffect(() => {
    void load()
    return () => controller.current?.abort()
  }, [load])

  const index = useMemo(() => listing.entries ? buildFolderIndex(listing.entries) : null, [listing.entries])
  const loading = listing.status === 'loading'
  const initialFailure = listing.status === 'failed' && !listing.entries
  const staleFailure = listing.status === 'failed' && listing.entries !== null

  let statusMessage = ''
  if (loading) statusMessage = listing.entries ? 'Refreshing…' : 'Loading Markdown folders…'
  else if (listing.status === 'refreshed') statusMessage = 'Listing refreshed.'

  return (
    <NavigateContext.Provider value={navigate}>
      <div className="app">
        <header className="app-header">
          <h1>MD Manager</h1>
          <p className="tagline">Browse the Markdown files in the Pi and Claude fixture folders. Read-only.</p>
        </header>
        <div className="toolbar">
          <Breadcrumbs key={pathname} crumbs={crumbsForRoute(route)} />
          <button type="button" className="refresh" onClick={() => void load()} disabled={loading}>
            <RefreshIcon />
            <span>{listing.entries && loading ? 'Refreshing…' : 'Refresh'}</span>
          </button>
        </div>
        <p role="status" className={statusMessage ? 'status' : 'status status-empty'}>{statusMessage}</p>
        {staleFailure && (
          <p role="alert" className="alert">
            Refresh failed. Showing the previous listing, which may be outdated. Check that the API is running and both fixture folders are readable, then try Refresh again.
          </p>
        )}
        <main className="content">
          {route.kind === 'home' && <SourceCards />}
          {route.kind === 'not-found' && <MissingFolder />}
          {route.kind === 'folder' && (
            initialFailure
              ? <div role="alert" className="alert">
                  <p>Unable to load Markdown folders. Check that the API is running and both fixture folders are readable.</p>
                  <button type="button" onClick={() => void load()}>Retry</button>
                </div>
              : index
                ? <FolderView source={route.source} segments={route.segments} index={index} />
                : <LoadingPlaceholders />
          )}
        </main>
      </div>
    </NavigateContext.Provider>
  )
}

function LoadingPlaceholders() {
  return (
    <div className="card-grid placeholders" aria-hidden="true">
      {Array.from({ length: 4 }, (_, position) => <div key={position} className="card card-placeholder" />)}
    </div>
  )
}

export default App
EOF
