import { request } from '@playwright/test'
import { apiUrl } from '../playwright.config.ts'

/** Playwright only waits for Vite; wait for the API too so the first test never races the server start. */
export default async function globalSetup() {
  const api = await request.newContext()
  const deadline = Date.now() + 30_000
  try {
    for (;;) {
      try {
        if ((await api.get(`${apiUrl}/api/entries`)).ok()) return
      } catch { /* not listening yet */ }
      if (Date.now() > deadline) throw new Error(`API did not become ready on ${apiUrl}`)
      await new Promise(resolve => setTimeout(resolve, 250))
    }
  } finally {
    await api.dispose()
  }
}
